import{_ as a,H as t,f as o,i as r}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"12 | 从基础功能拆解Kafka的架构设计与实现","description":"","frontmatter":{},"headers":[{"level":2,"title":"Kafka 系统架构","slug":"kafka-系统架构","link":"#kafka-系统架构","children":[]},{"level":2,"title":"协议和网络模块","slug":"协议和网络模块","link":"#协议和网络模块","children":[]},{"level":2,"title":"数据存储","slug":"数据存储","link":"#数据存储","children":[{"level":3,"title":"元数据存储","slug":"元数据存储","link":"#元数据存储","children":[]},{"level":3,"title":"消息数据","slug":"消息数据","link":"#消息数据","children":[]}]},{"level":2,"title":"生产者和消费者","slug":"生产者和消费者","link":"#生产者和消费者","children":[{"level":3,"title":"生产者","slug":"生产者","link":"#生产者","children":[]},{"level":3,"title":"消费者","slug":"消费者","link":"#消费者","children":[]}]},{"level":2,"title":"HTTP 协议支持和管控操作","slug":"http-协议支持和管控操作","link":"#http-协议支持和管控操作","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"上节课思考闭环","slug":"上节课思考闭环","link":"#上节课思考闭环","children":[]}],"relativePath":"深入拆解消息队列47讲/12｜从基础功能拆解Kafka的架构设计与实现.md","filePath":"深入拆解消息队列47讲/12｜从基础功能拆解Kafka的架构设计与实现.md","lastUpdated":1795450178000}'),i={name:"深入拆解消息队列47讲/12｜从基础功能拆解Kafka的架构设计与实现.md"};function s(p,e,n,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="_12-从基础功能拆解kafka的架构设计与实现" tabindex="-1">12 | 从基础功能拆解Kafka的架构设计与实现 <a class="header-anchor" href="#_12-从基础功能拆解kafka的架构设计与实现" aria-label="Permalink to &quot;12 | 从基础功能拆解Kafka的架构设计与实现&quot;">​</a></h1><p>你好，我是文强。</p><p>上节课我们分析了 RocketMQ 在通信协议、网络模块、存储模块、生产者、消费者这五个模块的设计思路。这节课同样还是分析 Kafka 在这五个模块的设计实现。</p><p>在学习的过程中，你会发现 Kafka 和 RocketMQ 的架构是非常像的，那为什么今天我们还要单独拿出一节课来分析 Kafka 呢？因为它们俩面对的场景是不一样的，一个是消息场景、一个是流场景，所以它们在底层的协议设计、存储模型、消费方式的实现上也是不一样的。而实现的不同，又导致了它们在功能和性能上的表现不一样。</p><p>接下来我们就从底层原理的角度来看一下，它们都有哪些异同点。</p><h2 id="kafka-系统架构" tabindex="-1">Kafka 系统架构 <a class="header-anchor" href="#kafka-系统架构" aria-label="Permalink to &quot;Kafka 系统架构&quot;">​</a></h2><p>首先来看一下 Kafka 的架构图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/1.jpeg" alt=""></a></p><p>如上图所示，Kafka 由 Producer、Broker、ZooKeeper、Consumer 四个模块组成。其中，ZooKeeper 用来存储元数据信息，集群中所有元数据都持久化存储在 ZooKeeper 当中。</p><p>Kafka 有 Topic 和分区的概念，分区就相当于 RocketMQ 的 MessageQueue。一个 Topic 可以包含一个或多个分区。消费方面通过 Group 来组织消费者和分区的关系。</p><p>到这你是不是发现了？Kafka 架构和 RocketMQ 非常像。从社区信息来看，RocketMQ 最初的设计应该参考过 Kafka，所以它们的架构和概念非常像，只是在具体实现方式上不太一样。比如概念上分区和 MessageQueue 的作用是一样的，元数据存储 ZooKeeper 和 NameServer的作用也是一样的。</p><p>前面我们讲过，使用 ZooKeeper 作为元数据存储服务会带来额外的维护成本、数据一致性和集群规模限制（主要是分区数）等问题。所以 RocketMQ 使用 NameServer 替代ZooKeeper，Kafka 3.0 使用内置的 Raft 机制替代 ZooKeeper，就是为了解决这几个问题。</p><p>从消息的生命周期来看，生产者也需要通过客户端寻址拿到元数据信息。客户端通过生产分区分配机制，选择消息发送到哪个分区，然后根据元数据信息拿到分区 Leader 所在的节点，最后将数据发送到 Broker。Broker 收到消息并持久化存储。消费端使用消费分组或直连分区的机制去消费数据，如果使用消费分组，就会经过消费者和分区的分配流程，消费到消息后，最后向服务端提交 Offset 记录消费进度，用来避免重复消费。</p><p>讲完基本概念和架构，我们继续围绕着基础篇的五个模块来分析一下 Kafka，先来看一下协议和网络模块。</p><h2 id="协议和网络模块" tabindex="-1">协议和网络模块 <a class="header-anchor" href="#协议和网络模块" aria-label="Permalink to &quot;协议和网络模块&quot;">​</a></h2><p>Kafka 是自定义的私有协议，经过多年发展目前有 V0、V1、V2 三个版本，稳定在 V2 版本。官方没有支持其他的协议，比如 HTTP，但是商业化的 Kafka 一般都会支持 HTTP 协议，原因还是 HTTP 协议使用的便捷性。</p><p>Kafka 协议从结构上来看包含协议头和协议体两部分，协议头包含基础通用的信息，协议体由于每个接口的功能参数不一样，内容结构上差异很大。</p><p>Kafka 协议的细节在第 03 讲已经详细讲过了，这里就不再重复。关于协议的更多详细信息你还可以参考官方的协议文档。</p><p>Kafka 服务端的网络层是基于 Java NIO 和 Reactor 来开发的，通过多级的线程调度来提高性能。Kafka 网络层细节在第 04 讲我们也讲过，遗忘的话可以去复习。</p><h2 id="数据存储" tabindex="-1">数据存储 <a class="header-anchor" href="#数据存储" aria-label="Permalink to &quot;数据存储&quot;">​</a></h2><p>下面我们继续来看 Kafka 的存储层，Kafka 同样分为元数据存储和消息数据存储两部分。</p><h3 id="元数据存储" tabindex="-1">元数据存储 <a class="header-anchor" href="#元数据存储" aria-label="Permalink to &quot;元数据存储&quot;">​</a></h3><p>上面我们说过，Kafka 的元数据是存储在 ZooKeeper 里面的。元数据信息包括 Topic、分区、Broker 节点、配置等信息。ZooKeeper 会持久化存储全量元数据信息，Broker 本身不存储任何集群相关的元数据信息。在 Broker 启动的时候，需要连接 ZooKeeper 读取全量元数据信息。</p><p>ZooKeeper 是一个单独的开源项目，它自带了集群组网、数据一致性、持久化存储、监听机制等等完整的能力。它的底层是基于 Zab 协议组件集群，有 Leader 节点和 Slave 节点的概念，数据写入全部在 Leader 节点完成，Slave 负责数据的读取工作。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/2.jpeg" alt=""></a></p><p>从 ZooKeeper 的角度来看，Kafka 只是它的一个使用者，Kafka 用 ZooKeeper 的标准使用方式向 ZooKeeper 集群上写入、删除、更新数据，以完成 Kafka 的元数据管理、集群构建等工作。所以每台 Broker 启动时，都会在 ZooKeeper 注册、监听一些节点信息，从而感知集群的变化。</p><p>另外，Kakfa 集群中的一些如消费进度信息、事务信息，分层存储元数据，以及 3.0 后的 Raft架构相关的元数据信息，都是基于内置 Topic 来完成存储的。把数据存储在内置 Topic 中，算是一个比较巧妙的思路了，也是一个值得借鉴的技巧。Kafka 中存储不同功能的元数据信息的Topic 列表如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/3.jpeg" alt=""></a></p><h3 id="消息数据" tabindex="-1">消息数据 <a class="header-anchor" href="#消息数据" aria-label="Permalink to &quot;消息数据&quot;">​</a></h3><p>在消息数据存储方面，Kafka 的数据是以分区为维度单独存储的。即写入数据到 Topic 后，根据生产分区分配关系，会将数据分发到 Topic 中不同的分区。此时底层不同分区的数据是存储在不同的“文件”中的，即一个分区一个数据存储“文件”。这里提到的“文件”也是一个虚指，在系统底层的表现是一个目录，里面的文件会分段存储。</p><p>如下图所示，当 Broker 收到数据后，是直接将数据写入到不同的分区文件中的。所以在消费的时候，消费者也是直接从每个分区读取数据。这个存储模型和 RocketMQ、RabbitMQ 都不像，这里的选择考虑和优劣势可以回顾第 05 讲。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/4.jpeg" alt=""></a></p><p>在底层数据存储中，Kafka 的存储结构是以 Topic 和分区维度来组织的。一个分区一个目录，目录名称是 TopicName + 分区号，结构如下图所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/kafka/data#ll</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 4096 2月  15 2020 __consumer_offsets-0</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 4096 2月  15 2020 __consumer_offsets-1</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 4096 2月  15 2020 __consumer_offsets-2</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 4096 2月  15 2020 __transaction_state-0</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 4096 2月  15 2020 __transaction_state-1</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 4096 2月  15 2020 __transaction_state-2</span></span></code></pre></div><p>每个分区的目录下，都会有 .index、.log、.timeindex 三类文件。其中，.log 是消息数据的存储文件，.index 是偏移量（offset）索引文件，.timeindex 是时间戳索引文件。两个索引文件分别根据 Offset 和时间来检索数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/data/data#ll __consumer_offsets-0</span></span>
<span class="line"><span>总用量 0</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 10485760 11月 19 2020 00000000000000000000.index</span></span>
<span class="line"><span>-rw-r--r-- 1 root root        0 2月  15 2020 00000000000000000000.log</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 10485756 11月 19 2020 00000000000000000000.timeindex</span></span>
<span class="line"><span>-rw-r--r-- 1 root root        0 2月  15 2020 leader-epoch-checkpoint</span></span></code></pre></div><p>在节点维度，也会持久存储当前节点的数据信息（如 BrokerID）和一些异常恢复用的Checkpoint 等数据。</p><p>由于每个分区存储的数据量会很大，分区数据也会进行分段存储。分段是在.log 进行的，文件分段的默认数据大小也是 1G，可以通过配置项来修改。</p><p>Kafka 提供了根据过期时间和数据大小清理的机制，清理机制是在 Topic 维度生效的。当数据超过配置的过期时间或者超过大小的限制之后，就会进行清理。清理的机制也是延时清理的机制，它是根据每个段文件进行清理的，即整个文件的数据都过期后，才会清理数据。</p><p>特别说明的是，根据大小清理的机制是在分区维度生效的，不是 Topic。即当分区的数据大小超过设置的大小，就会触发清理逻辑。这个机制和 RocketMQ 的清理机制是一致的，但RocketMQ 只提供了按节点维度配置的消息过期机制，所以相比之下，根据分区维度存储能带来一定的便捷。</p><p>在存储性能上，Kafka 的写入大量依赖顺序写、写缓存、批量写来提高性能。消费方面依赖批量读、顺序读、读缓存的热数据、零拷贝来提高性能。在这些技巧中，每个分区的顺序读写是高性能的核心。</p><p>接下来我们看一下客户端，看看 Kafka 的生产者和消费者的实现。</p><h2 id="生产者和消费者" tabindex="-1">生产者和消费者 <a class="header-anchor" href="#生产者和消费者" aria-label="Permalink to &quot;生产者和消费者&quot;">​</a></h2><p>Kafka 客户端在连接 Broker 之前需要经过客户端寻址，找到目标 Broker 的信息。在早期，Kafka 客户端是通过链接 ZooKeeper 完成寻址操作的，但是因为 ZooKeeper 的性能不够，如果大量的客户端都访问 ZooKeeper，那么就会导致 ZooKeeper 超载，从而导致集群异常。</p><p>所以在新版本的 Kafka 中，客户端是通过直连 Broker 完成寻址操作的，不会跟 ZooKeeper 交互。即 Broker 跟 ZooKeeper 交互，在本地缓存全量的元数据信息，然后客户端通过连接Broker 拿到元数据信息，从而避免对 ZooKeeper 造成太大负载。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/5.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/5.jpeg" alt=""></a></p><p>我们知道 RocketMQ 一直是通过 NameServer 完成寻址操作的，这就是我们说的虽然RocketMQ 和 Kafka 架构很像，但是实际的实现相差很大。</p><h3 id="生产者" tabindex="-1">生产者 <a class="header-anchor" href="#生产者" aria-label="Permalink to &quot;生产者&quot;">​</a></h3><p>生产者完成寻址后，在发送的时候可以将数据发送到 Topic 或者直接发送到分区。发送到Topic 时会经过生产分区分配的流程，即根据一定的策略将数据发送到不同的分区。</p><p>Kafka 提供了轮询和 KeyHash 两种策略。</p><p>轮询策略是指按消息维度轮询，将数据平均分配到多个分区。Key Hash 是指根据消息的 Key生成一个 Hash 值，然后和分区数量进行取余操作，得到的结果可以确定要将数据发送到哪个分区。生产消息分配的过程是在客户端完成的。</p><p>Kafka 协议提供了批量（Batch）发送的语义。所以生产端会在本地先缓存数据，根据不同的分区聚合数据后，再根据一定的策略批量将数据写入到 Broker。因为这个 Batch 机制的存在，客户端和服务端的吞吐性能会提高很多。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/6.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/6.jpeg" alt=""></a></p><p>这里多讲一点，客户端批量往服务端写有两种形式：一种是协议和内核就提供了 Batch 语义，一种是在业务层将一批数据聚合成一次数据发送。这两种虽然都是批量发送，但是它们的区别在于：</p><ol><li><p>第一种批量消息中的每条消息都会有一个 Offset，每条消息在 Broker 看来就是一条消息。第二种批量消息是这批消息就是一条消息，只有一个 Offset。</p></li><li><p>在消费端看来，第一种对客户端是无感的，一条消息就是一条消息。第二种需要消费者感知生产的批量消息，然后解析批量，逐条处理。</p></li></ol><h3 id="消费者" tabindex="-1">消费者 <a class="header-anchor" href="#消费者" aria-label="Permalink to &quot;消费者&quot;">​</a></h3><p>Kafka 的消费端只提供了 Pull（拉）模式的消费。即客户端是主动不断地去服务端轮询数据、获取数据，消费则是直接从分区拉取数据的。Kafka 提供了消费分组消费和直连分区消费两种模式，这两者的区别在于，是否需要进行消费者和分区的分配，以及消费进度谁来保存。</p><p>大部分情况下，都是基于消费分组消费。消费分组创建、消费者或分区变动的时候会进行重平衡，重新分配消费关系。Kafka 默认提供了 RangeAssignor（范围）、RoundRobinAssignor（轮询）、 StickyAssignor（粘性）三种策略，也可以自定义策略。消费分组模式下，一个分区只能给一个消费者消费，消费是顺序的。</p><p>当客户端成功消费数据后，会往服务端提交消费进度信息，此时服务端也不会删除具体的消息数据，只会保存消费位点信息。位点数据保存在内部的一个 Topic（__consumer_offset）中。消费端同样提供了自动提交和手动提交两种模式。当消费者重新启动时，会根据上一次保存的位点去消费数据，用来避免重复消费。</p><p>最后我们还是来看一下 Kafka 对 HTTP 协议和管控操作的支持。</p><h2 id="http-协议支持和管控操作" tabindex="-1">HTTP 协议支持和管控操作 <a class="header-anchor" href="#http-协议支持和管控操作" aria-label="Permalink to &quot;HTTP 协议支持和管控操作&quot;">​</a></h2><p>Kafka 内核是不支持 HTTP 协议的，如果需要支持，则需要在 Broker 前面挂一层代理。如Confluent 开源的 Kafka Rest。</p><p>管控的大部分操作是通过 Kafka Protocol 暴露的，基于四层的 TCP 进行通信。还有部分可以通过直连 ZooKeeper 完成管控操作。</p><p>在早期很多管控操作都是通过操作 ZooKeeper 完成的。后来为了避免对 ZooKeeper 造成压力，所有的管控操作都会通过 Broker 再封装一次，即客户端 SDK 通过 Kafka Protocol 调用Broker，Broker 再去和 ZooKeeper 交互。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/7.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/12/7.jpeg" alt=""></a></p><p>Kafka 命令行提供了管控、生产、消费、压测等功能，其底层就是通过客户端 SDK 和 Broker进行交互的。我们在代码里面也可以通过客户端 SDK 完成相应的操作，不用必须通过命令行。</p><p>因为历史的演进，在一些命令行里面，还残留着直连 ZooKeeper 的操作。而我们也可以通过直接操作 ZooKeeper 中的数据完成一些操作，比如更改配置、创建 Topic 等等。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>最后，我们再来总结一下 Kafka。</p><ol><li><p>协议层只支持私有的 Kafka Protocol 协议。</p></li><li><p>网络层是基于原生的 Java NIO 开发，底层也是通过多路复用、异步 IO、Reactor 模型等技术来提高网络模块的性能。</p></li><li><p>存储层是每个分区对应一份具体的存储文件，分区文件在底层会分段存储，同时支持基于时间和大小的数据过期机制。</p></li><li><p>元数据存储是通过 ZooKeeper 来实现的，所有的元数据都存储在 ZooKeeper 中。</p></li><li><p>客户端的访问同样也需要经过客户端寻址机制。老版本可以通过 ZooKeeper 获取元数据信息，新版本只能通过 Broker 拿到元数据信息。拿到所有元数据信息后，才会直连 Broker。</p></li><li><p>生产端支持将数据写入到 Topic 或指定写入某个分区，写入 Topic 时需要经过生产分区分配操作，选择出最终需要写入的分区，同时支持批量写入的语义。</p></li><li><p>消费端也有消费分组的概念，消费时需要在多个消费者和消费分组之间进行消费的负载均衡，同时也支持指定分区消费的模式。</p></li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请你按照基础篇的思路，描述一下 Kafka 从生产到消费的全过程？</p><p>欢迎在留言区分享你的答案，如果觉得有收获，也欢迎你把这节课分享给身边的朋友。我们下节课再见！</p><h2 id="上节课思考闭环" tabindex="-1">上节课思考闭环 <a class="header-anchor" href="#上节课思考闭环" aria-label="Permalink to &quot;上节课思考闭环&quot;">​</a></h2><p>请你按照基础篇的思路，描述一下 RocketMQ 从生产到消费的全过程，越详细越好。</p><p>跟经典的消息队列一样，RocketMQ 生产到消费也经过了生产者、Broker、消费者三个模块。我们通过 Remoting 协议来讲解一下大致的流程，具体如下：</p><p>在生产端，客户端通过四层的 TCP 协议和 NameServer 建立连接，通过 Remoting 协议从NameServer 获取到集群的元数据信息。根据元数据信息，和对应的 Broker 的建立 TCP 连接。如果客户端指定了目标 Topic，消息则先经过消息分区分配，然后才将数据发送到 Broker中。因为 Remoting 也没有支持 Batch 的协议，所以数据会直接发送到对应的 Broker，可以使用单向发送、同步发送、异步发送三种发送形式。</p><p>Broker 接收到数据后，会先使用 Remoting 反序列化数据。然后解析处理数据，将数据整合后，在底层会写入到同一个文件中，存储数据的时候会进行分段存储。如果是集群部署并设置了副本，则数据会分发到其他 Broker 的副本中。当数据过期后，Broker 会自动清理节点上的数据。</p><p>在消费端，可以先选择 Pull、Push、Pop 其中的一种消费模型。客户端同样需要先和NameServer 完成寻址操作。消费端有消费分组的概念，所以会先进行消费者和分区的消费关系分配的流程，然后消费者会和自己消费的分区的 Leader 所在的 Broker 建立连接。接着，客户端会使用 Remoting 协议从 Broker 消费数据。数据消费成功后，最后会提交消费进度。</p>`,79)])])}const f=a(i,[["render",s]]);export{E as __pageData,f as default};
